const TEST = msg.test_mode === true;
const STORE = TEST ? undefined : "persistent";
const get = (key) => STORE ? flow.get(key, STORE) : flow.get(key);
const set = (key, value) => STORE ? flow.set(key, value, STORE) : flow.set(key, value);
