    node.status({ fill: "red", shape: "ring", text: "configuração ausente" });
    return null;
}
const source = msg.data?.new_state ?? msg.payload?.new_state ?? msg.payload ?? {};
const entityId = String(source.entity_id ?? msg.data?.entity_id ?? msg.entity_id ?? "");
