    ["back_left_door", "porta traseira esquerda"],
    ["back_right_door", "porta traseira direita"],
    ["trunk", "porta-malas"]
];
const blockers = [];
if (["lock", "climate_on"].includes(command)) {
    for (const [key, labelText] of openSignals) {
