const anyoneAway =
    anyResidentAway ||
    msg.payload?.anyone_away === true ||
    peopleContext.anyone_away === true;

msg.payload.refresh_policy_version = 1;
msg.payload.refresh_policy_config = {
    away_interval_ms:
