flow.set("resident_notification_delivery_v4__test", null);
flow.set("resident_notifications_last_dry_run_v2__test", null);
flow.set("resident_notifications_last_test_event_at_v2", null);
node.status({ fill: "grey", shape: "ring", text: "estado de teste resetado" });
return null;

const now = Date.now();
const transition = (global.get("security_location_test_state_v1") ?? {}).transitions?.people;
const cases = {
    direct_home: ["resident_secondary", "home", "returning", true, now],
    invalid_direction: ["resident_primary", "approach", "leaving", true, now],
    unavailable: ["resident_secondary", "approach", "returning", false, now],
