    now - previousEpisode.started_at >= 6 * 60 * 60 * 1000);
if (!accepted && reason && reason !== "duplicate") {
    const signature = `${reason}:${msg.context_incoming_at}:${msg.context_previous_at}`;
    if (previousEpisode?.signature === signature && !expired) {
