const eligible = (id) => EXACT.has(id) || PREFIXES.some((prefix) => id.startsWith(prefix));

const testMode = msg.test_mode === true;
const list = Array.isArray(msg.ha_notifications) ? msg.ha_notifications : null;
if (list === null) {
    node.status({ fill: "red", shape: "ring", text: "lista do HA indisponível" });
    return null;
}
const now = Number.isFinite(msg.expiry_now) ? msg.expiry_now : Date.now();
const expired = [];
for (const entry of list) {
    const id = entry?.notification_id;
    if (typeof id !== "string" || !eligible(id)) continue;
    const createdAt = Date.parse(entry.created_at);
    if (!Number.isFinite(createdAt) || now - createdAt < MAX_AGE_MS) continue;
    expired.push({
        topic: id,
        payload: "",
        test_mode: testMode,
        _notification_expiry: { notification_id: id, created_at: entry.created_at, test_mode: testMode },
        notification: {
            source: "expiracao_notificacoes",
            operation: "dismiss",
            delivery: "queued",
            notification_id: id,
            test_mode: testMode
        }
    });
}
const clock = new Date(now).toISOString().slice(11, 16);
node.status({
    fill: expired.length ? "yellow" : "green",
    shape: "dot",
    text: `${testMode ? "TESTE: " : ""}${expired.length} vencida(s) de ${list.length} · ${clock} UTC`
});
return [expired];

const expiry = msg._notification_expiry ?? {};
const status = msg.notification_delivery?.status ?? "unknown";
const accepted = status === "accepted" || status === "simulated";
node.status({
    fill: accepted ? "green" : "red",
    shape: accepted ? "dot" : "ring",
    text: `${expiry.test_mode ? "TESTE: " : ""}${expiry.notification_id ?? "?"} → ${status}`
});
if (!accepted) node.warn({ expired_notification: expiry.notification_id ?? null, delivery_status: status });
return null;

// TESTE: the hub answered from its own dry-run; nothing was removed from Home Assistant.
const expiry = msg._notification_expiry ?? {};
msg.notification_expiry_dry_run = {
    simulated: true,
    dispatched: false,
    notification_id: expiry.notification_id ?? null,
    hub_status: msg.notification_delivery?.status ?? "unknown"
};
node.status({ fill: "blue", shape: "dot", text: `TESTE: ${expiry.notification_id ?? "?"} → ${msg.notification_delivery?.status ?? "?"}` });
return null;
